package com.zer0drv.blog.attachment.service;

import org.jsoup.parser.Parser;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

/** Only objects generated by this application's immutable UUID naming scheme are collectible. */
public final class AttachmentObjectKeys {
    private AttachmentObjectKeys() {}
    private static final Pattern KEY = Pattern.compile("[0-9]{4}(?:0[1-9]|1[0-2])/[a-f0-9]{32}\\.(?:jpg|jpeg|png|gif|webp)");
    private static final Pattern FILE = Pattern.compile("[a-f0-9]{32}\\.(?:jpeg|jpg|png|gif|webp)", Pattern.CASE_INSENSITIVE);

    public static boolean managed(String key) { return key != null && KEY.matcher(key).matches(); }

    /** Matching UUID basenames deliberately over-protects references across storage / old hostnames. */
    public static Set<String> references(String... texts) {
        Set<String> result = new HashSet<>();
        for (String text : texts) {
            if (text == null) continue;
            String decoded = Parser.unescapeEntities(text.replace("\\/", "/"), false);
            for (int i = 0; i < 3; i++) {
                var matcher = FILE.matcher(decoded);
                while (matcher.find()) result.add(matcher.group().toLowerCase(java.util.Locale.ROOT));
                try { decoded = URLDecoder.decode(decoded.replaceAll("%(?![0-9a-fA-F]{2})", "%25"), StandardCharsets.UTF_8); }
                catch (IllegalArgumentException invalidEncoding) { break; }
            }
        }
        return result;
    }

    public static String filename(String key) { return key.substring(key.lastIndexOf('/') + 1); }
}
